CREATE DATABASE IF NOT EXISTS cold_chain_logistics;
USE cold_chain_logistics;

CREATE TABLE IF NOT EXISTS reefers (
    id VARCHAR(50) PRIMARY KEY,
    name VARCHAR(100),
    carrier VARCHAR(100),
    rigId VARCHAR(50),
    status ENUM('critical', 'optimal', 'warning', 'ultracold'),
    statusLabel VARCHAR(50),
    temp DECIMAL(5,2),
    targetTemp DECIMAL(5,2),
    tolerance DECIMAL(5,2),
    cargo VARCHAR(200),
    doorStatus ENUM('SEALED', 'UNSEALED'),
    corridor VARCHAR(100),
    statusDetail VARCHAR(255),
    trajectoryText VARCHAR(100),
    trajectoryTrend ENUM('up', 'stable', 'down'),
    specs JSON,
    sparklineData JSON
);

CREATE TABLE IF NOT EXISTS excursion_incidents (
    id VARCHAR(50) PRIMARY KEY,
    reeferId VARCHAR(50),
    client VARCHAR(100),
    cargoLot VARCHAR(100),
    thermalPeak VARCHAR(50),
    thermalVariance VARCHAR(50),
    duration VARCHAR(50),
    resolutionVerdict VARCHAR(100),
    statusStyle ENUM('error', 'surface', 'neutral'),
    claimValue VARCHAR(50),
    penaltyValue VARCHAR(50),
    notes TEXT
);

CREATE TABLE IF NOT EXISTS customer_invoices (
    id VARCHAR(50) PRIMARY KEY,
    date DATE,
    client VARCHAR(100),
    corridor VARCHAR(100),
    corridorIcon VARCHAR(50),
    orderRef VARCHAR(50),
    grossFreight DECIMAL(12,2),
    gxpDeductions DECIMAL(12,2),
    incidentRef VARCHAR(50),
    netPayable DECIMAL(12,2),
    paymentStatus ENUM('pending', 'paid', 'sent'),
    paymentStatusLabel VARCHAR(50)
);

CREATE TABLE IF NOT EXISTS vendor_bills (
    id VARCHAR(50) PRIMARY KEY,
    vendorName VARCHAR(100),
    vendorId VARCHAR(50),
    amount DECIMAL(12,2),
    status VARCHAR(50),
    description TEXT,
    purchaseOrder VARCHAR(50),
    disbursementLedger VARCHAR(50),
    warrantyToken VARCHAR(50),
    terms VARCHAR(100),
    targetAsset VARCHAR(50),
    serviceLocation VARCHAR(100),
    paid BOOLEAN
);

CREATE TABLE IF NOT EXISTS journal_entries (
    id VARCHAR(50) PRIMARY KEY,
    title VARCHAR(150),
    date VARCHAR(50),
    autoPosted BOOLEAN,
    note TEXT,
    totalCheck DECIMAL(12,2)
);

CREATE TABLE IF NOT EXISTS journal_entry_lines (
    id INT AUTO_INCREMENT PRIMARY KEY,
    journalEntryId VARCHAR(50),
    accountCode VARCHAR(20),
    accountTitle VARCHAR(100),
    entityRef VARCHAR(100),
    debit DECIMAL(12,2) DEFAULT NULL,
    credit DECIMAL(12,2) DEFAULT NULL,
    highlight BOOLEAN DEFAULT FALSE,
    FOREIGN KEY (journalEntryId) REFERENCES journal_entries(id) ON DELETE CASCADE
);


